#include <bits/stdc++.h>
using namespace std;
using int64 = long long;
const int MOD = 1000000007;

int fastpow(int a, int b) {
    int ans = 1;
    while (b) {
        if (b & 1) ans = (int64)ans * a % MOD;
        a = (int64)a * a % MOD;
        b >>= 1;
    }
    return ans;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<vector<int>> p(n);
    int inv = fastpow(100, MOD - 2);
    for (int i = 0; i < n; ++i) {
        p[i].resize(n);
        for (int j = 0; j < n; ++j) {
            cin >> p[i][j];
            p[i][j] = (int64)p[i][j] * inv % MOD;
        }
    }

    vector<vector<int>> sub(n + 1);
    vector<vector<int>> id(n + 1, vector<int>(1 << n, -1));
    for (int sz = 0; sz <= n; ++sz) {
        for (int mask = 0; mask < (1 << n); ++mask) {
            if (__builtin_popcount(mask) == sz) {
                id[sz][mask] = (int)sub[sz].size();
                sub[sz].push_back(mask);
            }
        }
    }

    vector<unordered_map<int64, int>> dp(n + 1);
    dp[0][1] = 1;

    for (int i = 1; i <= n; ++i) {
        for (int s = 0; s < (1 << n); ++s) {
            int pr = 1;
            for (int j = 0; j < n; ++j) {
                // Use ternary to choose multiplier
                pr = (int64)pr * ((s & (1 << j)) ? p[i - 1][j] : (1 - p[i - 1][j] + MOD)) % MOD;
            }

            for (const auto &entry : dp[i - 1]) {
                int64 f = entry.first;
                int count = entry.second;
                int64 new_mask = 0;

                // Process each subset t of size i
                for (int t : sub[i]) {
                    // Iterate over set bits of t
                    int tmp = t;
                    while (tmp) {
                        int low = tmp & -tmp;
                        int j = __builtin_ctz(low);
                        if ((s & low) && (f & (1LL << id[i - 1][t ^ low]))) {
                            new_mask |= (1LL << id[i][t]);
                            break;
                        }
                        tmp ^= low;
                    }
                }

                dp[i][new_mask] = (dp[i][new_mask] + (int64)count * pr) % MOD;
            }
        }
    }

    cout << dp[n][1] << "\n";
    return 0;
}
